// Set up network interceptor to capture register request
window._capturedRequests = [];
const originalFetch = window.fetch;
window.fetch = function(...args) {
  const url = typeof args[0] === 'string' ? args[0] : args[0]?.url;
  const options = args[1] || {};
  window._capturedRequests.push({
    url,
    method: options.method || 'GET',
    body: options.body,
    headers: options.headers,
    timestamp: Date.now()
  });
  return originalFetch.apply(this, args);
};

// Also intercept XMLHttpRequest
const originalXHROpen = XMLHttpRequest.prototype.open;
const originalXHRSend = XMLHttpRequest.prototype.send;
XMLHttpRequest.prototype.open = function(method, url, ...rest) {
  this._capturedUrl = url;
  this._capturedMethod = method;
  return originalXHROpen.apply(this, [method, url, ...rest]);
};
XMLHttpRequest.prototype.send = function(body) {
  window._capturedRequests.push({
    url: this._capturedUrl,
    method: this._capturedMethod,
    body: body,
    timestamp: Date.now()
  });
  return originalXHRSend.apply(this, [body]);
};

"Network interceptor installed. Now fill the form and click register.";
